   268    static inline void process_seac (CFF1CSInterpEnv &env, ExtentsParam& param)
   269    {
   270      unsigned int  n = env.argStack.get_count ();
   271      Point delta;
   272      delta.x = env.argStack[n-4];
   273      delta.y = env.argStack[n-3];
   274      hb_codepoint_t base = param.cff->std_code_to_glyph (env.argStack[n-2].to_int ());
