    88  struct CFF1CSOpSet : CSOpSet<Number, OPSET, CFF1CSInterpEnv, PARAM, PATH>
    89  {
    90    /* PostScript-originated legacy opcodes (OpCode_add etc) are unsupported */
    91    /* Type 1-originated deprecated opcodes, seac behavior of endchar and dotsection are supported */
    92
    93    static inline void process_op (OpCode op, CFF1CSInterpEnv &env, PARAM& param)
    94    {
    95      switch (op) {
    96        case OpCode_dotsection:
    97          SUPER::flush_args_and_op (op, env, param);
    98          break;
    99
   100        case OpCode_endchar:
   101          OPSET::check_width (op, env, param);
   102          if (env.argStack.get_count () >= 4)
   103          {
   104            OPSET::process_seac (env, param);
   105          }
   106          OPSET::flush_args_and_op (op, env, param);
   107          env.set_endchar (true);
   108          break;
   109
   110        default:
   111          SUPER::process_op (op, env, param);
   112      }
   113    }
