   115    static inline void check_width (OpCode op, CFF1CSInterpEnv &env, PARAM& param)
   116    {
   117      if (!env.processed_width)
   118      {
   119        bool  has_width = false;
   120        switch (op)
   121        {
   122          case OpCode_endchar:
   123          case OpCode_hstem:
   124          case OpCode_hstemhm:
   125          case OpCode_vstem:
   126          case OpCode_vstemhm:
   127          case OpCode_hintmask:
   128          case OpCode_cntrmask:
   129            has_width = ((env.argStack.get_count () & 1) != 0);
   130            break;
   131          case OpCode_hmoveto:
   132          case OpCode_vmoveto:
   133            has_width = (env.argStack.get_count () > 1);
   134            break;
   135          case OpCode_rmoveto:
   136            has_width = (env.argStack.get_count () > 2);
   137            break;
   138          default:
   139            return;
   140        }
   141        env.set_width (has_width);
   142      }
   143    }
